import re
from datetime import datetime

_DIGITS = frozenset("0123456789")
_UPDATED_FORMATS = ("%Y-%m-%d", "%m/%d/%Y", "%Y-%m-%dT%H:%M:%S")
_OPT_OUT_VALUES = {"y", "yes", "true", "1"}


def _field(row, key):
    return row.get(key) or ""


def _all_digits(s):
    return bool(s) and all(c in _DIGITS for c in s)


def _normalize_email(raw):
    """Return the normalized email, or "" if it is not valid."""
    s = raw
    m = re.search(r"<([^<>]*)>", s)
    if m:
        s = m.group(1)
    s = s.strip().lower()

    if s.count("@") != 1:
        return ""
    local, domain = s.split("@")

    if domain in ("gmail.com", "googlemail.com"):
        local = local.replace(".", "").split("+", 1)[0]
        domain = "gmail.com"

    if (not local
            or "." not in domain
            or domain.startswith(".")
            or domain.endswith(".")):
        return ""
    return local + "@" + domain


def _normalize_phone(raw):
    """Return the normalized 10-digit phone, or "" if it is not valid."""
    s = raw
    m = re.search(r"ext|x|#", s, re.IGNORECASE)
    if m:
        s = s[:m.start()]
    digits = "".join(c for c in s if c in _DIGITS)
    if len(digits) == 11 and digits[0] == "1":
        digits = digits[1:]
    if len(digits) == 10 and digits[0] not in "01":
        return digits
    return ""


def _normalize_zip(raw):
    """Return a 5-digit ZIP, or "" if it cannot be made into one."""
    z = raw.strip()
    if re.fullmatch(r"[0-9]{5}-[0-9]{4}", z):
        z = z[:5]
    if len(z) == 4 and _all_digits(z):
        z = "0" + z
    if len(z) == 5 and _all_digits(z):
        return z
    return ""


def _normalize_name(raw):
    n = raw.strip()
    if n.isupper() or n.islower():
        n = n.title()
    return n


def _parse_updated(raw):
    s = raw.strip()
    for fmt in _UPDATED_FORMATS:
        try:
            return datetime.strptime(s, fmt)
        except ValueError:
            pass
    raise ValueError(f"Unrecognized 'updated' value: {raw!r}")


def _parse_opted_out(raw):
    return raw.strip().lower() in _OPT_OUT_VALUES


def _parse_tags(raw):
    return {t.strip().lower() for t in re.split(r"[;,]", raw) if t.strip()}


def _pick(members, field):
    """Pick a value from the group: manual first, then latest updated, then earliest row."""
    candidates = [m for m in members if m[field]]
    if not candidates:
        return ""
    best = max(candidates,
               key=lambda m: (m["is_manual"], m["updated"], -m["idx"]))
    return best[field]


def dedupe_contacts(rows):
    # Steps 1-9: normalize each row and drop rows with no valid email or phone.
    records = []
    for idx, row in enumerate(rows):
        email = _normalize_email(_field(row, "email"))
        phone = _normalize_phone(_field(row, "phone"))
        if not email and not phone:
            continue
        source = _field(row, "source").strip().lower()
        records.append({
            "idx": idx,
            "first_name": _normalize_name(_field(row, "first_name")),
            "last_name": _normalize_name(_field(row, "last_name")),
            "zip": _normalize_zip(_field(row, "zip")),
            "email": email,
            "phone": phone,
            "source": source,
            "is_manual": source == "manual",
            "updated": _parse_updated(_field(row, "updated")),
            "tags": _parse_tags(_field(row, "tags")),
            "opted_out": _parse_opted_out(_field(row, "opted_out")),
        })

    # Step 10: union-find over shared keys (transitive matching).
    parent = list(range(len(records)))

    def find(x):
        while parent[x] != x:
            parent[x] = parent[parent[x]]
            x = parent[x]
        return x

    def union(a, b):
        ra, rb = find(a), find(b)
        if ra != rb:
            if ra < rb:
                parent[rb] = ra
            else:
                parent[ra] = rb

    seen = {}
    for k, rec in enumerate(records):
        keys = []
        if rec["email"]:
            keys.append(("email", rec["email"]))
        if rec["phone"] and rec["last_name"]:
            keys.append(("phone", rec["phone"], rec["last_name"].casefold()))
        for key in keys:
            if key in seen:
                union(seen[key], k)
            else:
                seen[key] = k

    groups = {}
    for k in range(len(records)):
        groups.setdefault(find(k), []).append(k)

    # Step 12: order people by their earliest input row.
    ordered = sorted(groups.values(), key=lambda g: g[0])

    # Step 11: build one output record per person.
    result = []
    for group in ordered:
        members = [records[k] for k in group]
        tags = set().union(*(m["tags"] for m in members))
        result.append({
            "first_name": _pick(members, "first_name"),
            "last_name": _pick(members, "last_name"),
            "zip": _pick(members, "zip"),
            "email": _pick(members, "email"),
            "phone": _pick(members, "phone"),
            "source": _pick(members, "source"),
            "tags": ";".join(sorted(tags)),
            "opted_out": "Y" if any(m["opted_out"] for m in members) else "N",
            "updated": max(m["updated"] for m in members).strftime("%Y-%m-%d"),
        })
    return result
